const initialLoading = computed(() => loading.value && !snapshot.value)
const refreshing = computed(() => loading.value && Boolean(snapshot.value))
const filteredBannedWords = computed(() => {
  const keyword = form.bannedSearch.trim().toLowerCase()
  return (snapshot.value?.bannedWords || []).filter((item) => !keyword || `${item.word} ${item.memo || ''}`.toLowerCase().includes(keyword))
})
const filteredSynonyms = computed(() => {
  const keyword = form.synonymSearch.trim().toLowerCase()
  return (snapshot.value?.synonyms || []).filter(
    (item) => !keyword || item.representativeWord.toLowerCase().includes(keyword) || item.synonymArray.some((word) => word.toLowerCase().includes(keyword)),
  )
})

function hydrate(value: AdvancedPolicySnapshot) {
  snapshot.value = value
  form.deleteTerm = Number(value.deleteTerm || 30)
  const adminLimit = value.notebookLimits.find((item) => item.group === 'admin')?.limit ?? -1
  const userLimit = value.notebookLimits.find((item) => item.group === 'user')?.limit ?? 5
  form.adminUnlimited = adminLimit < 0
  form.userUnlimited = userLimit < 0
  form.adminLimit = adminLimit > 0 ? adminLimit : 10
  form.userLimit = userLimit > 0 ? userLimit : 5
}

async function load() {
  const ticket = policyRequest.start()
  loading.value = true
  error.value = ''
  try {
    const result = await getAdvancedPolicySnapshot()
    if (!ticket.isLatest()) return
    hydrate(result)
  } catch (reason) {
    if (!ticket.isLatest()) return
    error.value = reason instanceof Error ? reason.message : '세부 정책을 불러오지 못했습니다.'
  } finally {
    if (ticket.isLatest()) loading.value = false
  }
}

async function runSave(key: string, action: () => Promise<unknown>, message: string) {
  if (!writesEnabled.value || saving.value) return false
  saving.value = key
  try {
    await action()
    notify(message, 'success')
    await load()
    return true
  } catch (reason) {
    notify(reason instanceof Error ? reason.message : '정책을 변경하지 못했습니다.', 'error')
    return false
  } finally {
    saving.value = ''
  }
}

async function addBannedWord() {
  const word = form.bannedWord.trim()
  if (word.length < 2 || word.length > 10) {
    notify('금칙어는 2~10자로 입력하십시오.', 'error')
    return
  }
  if (snapshot.value?.bannedWords.some((item) => item.word === word)) {
    notify('이미 등록된 금칙어입니다.', 'error')
    return
  }
  if ((snapshot.value?.bannedWords.length || 0) >= 1000) {
    tabLoading.shared = false
