    if (lastPage) return await loadSharedApps(lastPage)
  } catch (reason) {
    if (!ticket.isLatest()) return
    tabError.shared = reason instanceof Error ? reason.message : '공유 앱 목록을 불러오지 못했습니다.'
  } finally {
    if (ticket.isLatest()) tabLoading.shared = false
  }
}

function changeTab(tab: CatalogTab) {
  activeTab.value = tab
  if (tab === 'library' && !tabLoaded.library && !tabLoading.library) void loadLibrary()
  if (tab === 'shared' && sharedFilters.userId && !tabLoaded.shared && !tabLoading.shared) void loadSharedApps()
}

