import fs from 'node:fs'
import path from 'node:path'

const filePath = path.resolve(process.argv[2] || 'public/config/runtime.json')
const requiredStrings = ['appName', 'environment', 'backendBaseUrl', 'authSsoUrl']
const requiredBooleans = ['mockMode', 'enablePolicyWrites', 'enableMonitoring']
// 상대 경로가 실제로 same-origin인지 확인할 때 쓰는 sentinel origin.
const RELATIVE_BASE = 'https://relative.invalid/'
// 평문 http를 예외로 허용하는 개발용 loopback host.
const LOOPBACK_HOSTNAMES = ['localhost', '127.0.0.1', '[::1]']

function fail(message) {
  console.error(`[runtime-config] ${message}`)
  process.exit(1)
}

// allowedHosts 항목은 `host` 또는 `host:port`만 허용하고 비교 가능한 형태로 정규화한다.
function normalizeHostEntry(entry, protocol) {
  const trimmed = entry.trim()
  let parsed
  try {
    parsed = new URL(`${protocol}//${trimmed}`)
  } catch {
    fail(`allowedHosts 항목은 host 또는 host:port 형식이어야 합니다: ${entry}`)
  }
  if (parsed.username || parsed.password || parsed.pathname !== '/' || parsed.search || parsed.hash || !parsed.hostname) {
    fail(`allowedHosts 항목은 host 또는 host:port 형식이어야 합니다: ${entry}`)
  }
  return parsed.host
}

if (!fs.existsSync(filePath)) fail(`파일이 없습니다: ${filePath}`)

let config
try {
  config = JSON.parse(fs.readFileSync(filePath, 'utf8'))
} catch (error) {
  fail(`JSON 파싱 실패: ${error instanceof Error ? error.message : String(error)}`)
}

for (const key of requiredStrings) {
  if (typeof config[key] !== 'string' || !config[key].trim()) fail(`${key}는 비어 있지 않은 문자열이어야 합니다.`)
}

for (const key of requiredBooleans) {
  if (typeof config[key] !== 'boolean') fail(`${key}는 boolean이어야 합니다.`)
}

if (config.authLogoutUrl != null && typeof config.authLogoutUrl !== 'string') {
  fail('authLogoutUrl은 문자열이어야 합니다.')
}

if (!Number.isInteger(config.requestTimeoutMs) || config.requestTimeoutMs < 1000 || config.requestTimeoutMs > 120000) {
  fail('requestTimeoutMs는 1,000~120,000 사이의 정수여야 합니다.')
}

if (!Number.isInteger(config.pollIntervalMs) || config.pollIntervalMs < 5000 || config.pollIntervalMs > 300000) {
  fail('pollIntervalMs는 5,000~300,000 사이의 정수여야 합니다.')
}

if (!Array.isArray(config.allowedHosts) || config.allowedHosts.some((host) => typeof host !== 'string' || !host.trim())) {
  fail('allowedHosts는 문자열 배열이어야 합니다.')
}

